import { ref } from 'vue'
import mapboxgl from 'mapbox-gl'
import MapboxGeocoder from '@mapbox/mapbox-gl-geocoder'

/** Basemap URL là style Mapbox; đổi style không làm đổi dataset Concordia. */
const mapStyles = [
  { title: 'Streets', value: 'mapbox://styles/mapbox/streets-v11' },
  { title: 'Outdoors', value: 'mapbox://styles/mapbox/outdoors-v11' },
  { title: 'Light', value: 'mapbox://styles/mapbox/light-v10' },
  { title: 'Dark', value: 'mapbox://styles/mapbox/dark-v10' },
  { title: 'Satellite Streets', value: 'mapbox://styles/mapbox/satellite-streets-v11' },
  { title: 'Navigation Day', value: 'mapbox://styles/mapbox/navigation-day-v1' },
  { title: 'Navigation Night', value: 'mapbox://styles/mapbox/navigation-night-v1' },
]

/**
 * Input: getMap() và public accessToken của owner. Output: refs cho toolbar CityView và attach() gắn controls.
 * Search do MapboxGeocoder xử lý; module chỉ quản lý lỗi/gợi ý, chọn basemap, Hide và menu nền.
 * controlsVisible=false ẩn cả hai vùng HUD bằng v-show, không đổi dữ liệu hoặc kích thước canvas.
 * Owner gọi attach() một lần sau tạo map; map.remove() gọi onRemove của từng control để dọn DOM/listener.
 */
export function useMapControls({ getMap, accessToken }) {
  const controlsElement = ref(null)
  const searchError = ref('')
  const controlsVisible = ref(true)
  const layersOpen = ref(false)
  const mapStyle = ref('mapbox://styles/mapbox/dark-v10')

  function attach() {
    const map = getMap()
    // Geocoder nhận chuỗi địa điểm và tự xử lý gợi ý/marker/flyTo khi chọn.
    // Handler error ngăn EventEmitter phát lỗi không được xử lý khi API từ chối.
    const geocoder = new MapboxGeocoder({ accessToken, mapboxgl, placeholder: 'Search address or place' })
    geocoder.on('loading', () => (searchError.value = ''))
    geocoder.on('clear', () => (searchError.value = ''))
    geocoder.on('error', () => {
      searchError.value = 'Could not search locations. Check your token and connection.'
    })
    map.addControl(geocoder, 'top-right')
    map.addControl(new mapboxgl.NavigationControl(), 'top-right')

    // Input: DOM toolbar đã được Vue render. Output: Mapbox xếp toolbar cùng
    // search/zoom; khi map.remove(), onRemove tháo node trước khi Vue unmount.
    map.addControl(
      {
        onAdd: () => controlsElement.value,
        onRemove: () => controlsElement.value?.remove(),
      },
      'top-right',
    )
    map.addControl(new mapboxgl.AttributionControl({ compact: false }), 'bottom-right')
  }

  return { controlsElement, searchError, controlsVisible, layersOpen, mapStyle, mapStyles, attach }
}
